type Table<K extends string | number, V> = { entries: Map<K, V>; fallback: V };
const lookup = <K extends string | number, V>(t: Table<K, V>, k: K) => t.entries.get(k) ?? t.fallback;
const STATUS: Table<number, string> = { entries: new Map([[200, "OK"], [404, "Not Found"]]), fallback: "Unknown" };
